ev=read(P/'PRE_SOLVE_ORIENTATION_EVIDENCE_R1.json');keys=read(P/'KEYBOARD_88_KEY_TABLE_R1.json')['keys'];width=float(np.median([k['width'] for k in keys if k['color']=='WHITE']));L=float(np.mean([v['canonical_wrist_to_middle_mcp_m'] for v in ev.values()]));W=float(np.mean([v['canonical_palm_width_m'] for v in ev.values()]));blackheight=max(s['z'] for k in keys for s in k['key_top_playable_surface']);margin=math.degrees(math.atan(width/L));headmax=max(abs(r['heading_deg']) for v in ev.values() for r in v['source_wrist_observations']);pitchmax=max(abs(r['longitudinal_elevation_deg']) for v in ev.values() for r in v['source_wrist_observations']);rollmax=max(abs(math.degrees(math.atan2(r['wrist_rotation_canonical'][2][0],r['wrist_rotation_canonical'][2][2]))) for v in ev.values() for r in v['source_wrist_observations'])
