policy={'phase':'PIANO_KEYBOARD_LOW_DOF_ROOT_POSE_VALIDATION_R1','model_order':['A','B_ONLY_IF_GATE_PASSES'],'MODEL_A':{'DOF':['XYZ','YAW'],'yaw_axis':'canonical keyboard +Z','pitch_roll':0},'MODEL_B':{'DOF':['XYZ','YAW','PITCH','ROLL'],'rotation_order':'Rz(yaw) @ Rx(pitch) @ Ry(roll)','pitch_axis':'canonical X, raise/lower longitudinal approach','roll_axis':'canonical Y, bank across keyboard','gate_required':True},'bounds_degrees':{'YAW':[-yaw,yaw],'PITCH':[-pitch,pitch],'ROLL':[-roll,roll]},'evidence':{'source_heading_abs_max_deg':headmax,'source_longitudinal_elevation_abs_max_deg':pitchmax,'source_bank_abs_max_deg':rollmax,'white_key_width_m':width,'black_top_above_white_m':blackheight,'canonical_palm_width_m':W,'wrist_to_middle_mcp_m':L,'one_key_steering_margin_deg':margin},'bound_derivation':'Yaw = round up5deg(max approved source wrist heading + atan(one white width/palm length)); pitch/roll similarly observed source inclination plus geometric black-key step over palm length/width. These are conservative audit search caps allowing source-heading compensation, NOT measured human range-of-motion limits. No result-driven expansion.','anatomical_orientation_prior':{'desired_total_heading':'rear-facing within atan(palm_width/palm_length) before penalty','heading_soft_corridor_deg':math.degrees(math.atan(W/L)),'penalty':'outside corridor, palm-length times angular exceedance is a spatial residual; cannot obtain pass by sideways/twisted placement'},'scale':1,'finger_corrections':False,'point_target_locations':'exact previous white front+25mm / black front+15mm and approved dynamic key surfaces','fingering_permutations_in_solver':False,'source_pose_claim':'PRODUCT_SPATIALIZATION_LAYER, NOT measured wrist-world mocap'}
